--region handler
function UIFastNettingFishingDialog:OnClickCloseHandler()
    if self.cb then
        self.cb()
    end
    UIModule.BackDialog()
end

function UIFastNettingFishingDialog:OnClickBtnConfirmHandler()
    self._fishComp:NetFishReq(self.fishPlaceId, self.consumeGoodsNum, function(rewards, newFishIds)
        -- 扣除渔网
        GoodsUtils.DrawRewards({
            {
                goodsId = self.consumeGoodsId,
                num = -self.consumeGoodsNum
            }
        })
        local fishIdsHash = {}
        for _, fishId in ipairs(newFishIds) do
            fishIdsHash[checkString(fishId)] = true
        end

        for _, reward in ipairs(rewards) do
            reward.isNew = checkBool(fishIdsHash[checkString(reward.goodsId)])
        end

        UIModule.OpenDialog({
            id = Constants.UITypeIds.UIFastNettingFishCatchingAnimationDialog,
            parameters = {
                rewards = rewards,
                placeId = self.parameters.placeId,
                cb = self.parameters.cb
            }
        },{
            { id = Constants.UITypeIds.UIFastNettingFishDialog }
        })
    end)
end

function UIFastNettingFishingDialog:OnSliderValueChangedHandler(value)
    local num = value * self.multi
    self.sliderScr:SetTextNumber(num)
    UICommonUtils.FillCommonBtnConsumePop(self.CommonBtnConsumePop, self.consumeGoodsId, value)
    self.consumeGoodsNum = value
end
--endregion handler

--region private
function UIFastNettingFishingDialog:RefreshUI()
    self.sliderScr:RefreshNode(1,1,self.ownCount, Bind(self, self.OnSliderValueChangedHandler))
    self.sliderScr:SetTextNumber(self.multi)
    UICommonUtils.FillCommonBtnConsumePop(self.CommonBtnConsumePop, self.consumeGoodsId, 1)
    self.consumeGoodsNum = 1
end

--endregion private

